"total":150,"difference":0,"attribute_origin":"NPC — estimativa narrativa e tendência regional","sheet_row":169},{"house_id":"wyvernspur","house_name":"Wyvernspur","region_id":"crownlands","hierarchy":"Vassala direta","overlord":"Von der Harten","defense":45,"influence":34,"lands":29,"law":45,"population":29,"power":34,"wealth":34,"budget":250,"total":250,"difference":0,"attribute_origin":"NPC — estimativa narrativa e tendência regional","sheet_row":170},{"house_id":"yellander","house_name":"Yellander","region_id":"horselands","hierarchy":"Terceiro nível","overlord":"Mistwind","defense":10,"influence":26,"lands":31,"law":13,"population":23,"power":18,"wealth":29,"budget":150,"total":150,"difference":0,"attribute_origin":"Redistribuição oficial — torre; Defesa 7→10, Riqueza 32→29; total 150 mantido","sheet_row":171}]$cca_noble_stat_source_2026_11_03$::jsonb) AS x(
  house_id text,house_name text,region_id text,hierarchy text,overlord text,
  defense integer,influence integer,lands integer,law integer,population integer,
  power integer,wealth integer,budget integer,total integer,difference integer,
  attribute_origin text,sheet_row integer
 )
)
INSERT INTO public.spy_noble_house_stats(
 house_id,house_name,region_id,hierarchy,overlord,
 defense,influence,lands,law,population,power,wealth,
 budget,total,difference,attribute_origin,source_row
)
SELECT x.house_id,x.house_name,x.region_id,x.hierarchy,x.overlord,
 x.defense,x.influence,x.lands,x.law,x.population,x.power,x.wealth,
 x.budget,x.total,x.difference,x.attribute_origin,x.sheet_row
FROM input x JOIN public.house_catalog c ON c.id=x.house_id AND c.public_reviewed=true
WHERE lower(replace(c.name,' ',''))=lower(replace(x.house_name,' ',''))
ORDER BY x.house_id;

DO $asserts$ BEGIN
 IF (SELECT count(*) FROM public.spy_noble_house_stats)<>170
 THEN RAISE EXCEPTION 'Importação incompleta: esperado 170 Casas'; END IF;
 IF (SELECT count(*) FROM public.spy_noble_house_stats s JOIN public.house_catalog c ON c.id=s.house_id
  WHERE c.public_reviewed IS NOT TRUE)<>0
 THEN RAISE EXCEPTION 'Casa não revisada identificada'; END IF;
 IF (SELECT count(*) FROM public.noble_house_sheets)<>8
 THEN RAISE EXCEPTION 'Fichas dos jogadores alteradas'; END IF;
END $asserts$;

-- Lista pública: nomes, IDs e regiões, sem Lei/atributos.
CREATE OR REPLACE FUNCTION public.spy_public_noble_targets()
RETURNS TABLE(id text,name text,region text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $fn$
BEGIN
 IF auth.uid() IS NULL OR NOT public.campaign_access_active()
 THEN RAISE EXCEPTION 'Lista pública de Casas indisponível para esta sessão'; END IF;
 RETURN QUERY
 SELECT c.id,c.name,c.region
 FROM public.house_catalog c
 WHERE c.public_reviewed IS TRUE
 ORDER BY c.region,c.name,c.id;
END $fn$;
REVOKE ALL ON FUNCTION public.spy_public_noble_targets() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.spy_public_noble_targets() TO authenticated;

-- Metadados para resolução da dificuldade SOMENTE pelo Narrador.
-- A existência da ficha prevalece sobre o atributo importado; o Narrador
-- deverá calcular a Lei operacional e os bônus pela engine de Casa.
CREATE OR REPLACE FUNCTION public.spy_narrator_noble_defense_source(p_house text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=public,pg_temp AS $fn$
DECLARE v record;
BEGIN
 IF auth.uid() IS NULL OR NOT public.campaign_access_active() OR
    NOT public.is_campaign_admin()
 THEN RAISE EXCEPTION 'Dificuldade de Casa-alvo reservada ao Narrador'; END IF;
 SELECT c.id,c.name,c.region,
  EXISTS(SELECT 1 FROM public.noble_house_sheets n WHERE n.house_id=c.id) AS has_sheet,
  s.law AS imported_law,s.source_row AS imported_row,
  s.source_spreadsheet_id AS imported_spreadsheet
 INTO v
 FROM public.house_catalog c
 LEFT JOIN public.spy_noble_house_stats s ON s.house_id=c.id
 WHERE c.id=p_house AND c.public_reviewed IS TRUE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Casa nobre desconhecida ou não homologada'; END IF;
 RETURN jsonb_build_object(
  'id',v.id,'name',v.name,'region',v.region,'hasOperationalSheet',v.has_sheet,
  'importedLaw',v.imported_law,'importedSourceRow',v.imported_row,
  'source',CASE WHEN v.has_sheet THEN 'operational_sheet'
   WHEN v.imported_law IS NOT NULL THEN 'imported_spreadsheet'
   ELSE 'missing_sheet_and_spreadsheet' END);
END $fn$;
REVOKE ALL ON FUNCTION public.spy_narrator_noble_defense_source(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.spy_narrator_noble_defense_source(text) TO authenticated;
COMMIT;
SELECT count(*) AS imported_houses,count(DISTINCT region_id) AS regions,
 min(law) AS min_law,max(law) AS max_law
 FROM public.spy_noble_house_stats;
